{
 "$schema": "urn:semantic-agent-schema:published-language:abstract:v1",
 "$id": "urn:example:sample:usecase:v1",
 "title": "ユースケース",
 "description": "外で直した。利用者が目的を果たすまでの手順である。",
 "type": "object",
 "required": [
  "$schema",
  "id",
  "goal"
 ],
 "properties": {
  "$schema": {
   "const": "urn:example:sample:usecase:v1"
  },
  "id": {
   "title": "ID",
   "description": "ユースケースを区別する名前である。",
   "x-prompt": {
    "rules": []
   },
   "type": "string",
   "pattern": "^U[0-9]+$"
  },
  "goal": {
   "title": "目的",
   "description": "利用者が果たしたいことである。",
   "x-prompt": {
    "rules": [
     {
      "id": "goal-is-outcome",
      "rule": "利用者が得る結果を書く。",
      "why": "手段を書くと、目的が果たせたかを決められない。",
      "check": "結果を表す名詞句かを見る。",
      "bad": [
       {
        "value": "注文フォームに入力する",
        "note": "利用者の操作（手段）で、得る結果ではない。"
       }
      ],
      "good": [
       {
        "value": "注文した品の受け取り"
       }
      ]
     }
    ]
   },
   "type": "string"
  },
  "calls": {
   "title": "呼ぶユースケース",
   "description": "途中で呼ぶほかのユースケースの並びである。",
   "x-prompt": {
    "rules": []
   },
   "type": "array",
   "items": {
    "type": "string"
   }
  }
 }
}
